SELECT id, entity_type, action_type, entity_id, before_snapshot, after_snapshot, summary,
       status, requested_by, requested_at, reviewed_by, reviewed_at, reject_reason, created_at, updated_at
FROM audit_request


        AND entity_type = #{entityType}


        AND status = #{status}


        AND action_type = #{actionType}


ORDER BY requested_at DESC

SELECT id, entity_type, action_type, entity_id, before_snapshot, after_snapshot, summary,
       status, requested_by, requested_at, reviewed_by, reviewed_at, reject_reason, created_at, updated_at
FROM audit_request
WHERE entity_type = #{entityType}
  AND entity_id = #{entityId}
  AND status = 'PENDING'
